#!/usr/bin/env node
// lrapr-t006/u5-ingest-linkfree — step 1b: the pinned commit is NOT the target of
// the annotated tag v0.72.0; it is that commit's child. This driver establishes the
// exact blob-level delta between the tag target and the pinned commit, so the
// discrepancy is recorded with bytes rather than described.

import { createHash } from "node:crypto";
import { appendFileSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const EVIDENCE = resolve(HERE, "..");
const CONSENT = "VL-LEGACY-CORPUS-2026-08-10";

if (process.env.VERSIONLESS_NETWORK_MODE !== "consented") process.exit(2);
if (process.env.VERSIONLESS_CONSENT_ID !== CONSENT) process.exit(2);

const CANON = "EddieHubCommunity/BioDrop";
const sha256 = (b) => createHash("sha256").update(b).digest("hex");

async function get(url, phase) {
  const at = new Date().toISOString();
  const res = await fetch(url, {
    method: "GET",
    redirect: "manual",
    headers: {
      accept: "application/vnd.github+json",
      "user-agent": "versionless-legacy-corpus-ingest",
      "accept-encoding": "identity",
    },
  });
  const bytes = Buffer.from(await res.arrayBuffer());
  const entry = { at, phase, method: "GET", url, status: res.status, bytes: bytes.length, sha256: sha256(bytes) };
  appendFileSync(resolve(EVIDENCE, "probe-ledger.ndjson"), JSON.stringify(entry) + "\n");
  if (res.status !== 200) throw new Error(`non-200 ${res.status} for ${url}`);
  return JSON.parse(bytes.toString("utf8"));
}

const probe = JSON.parse(readFileSync(resolve(EVIDENCE, "probe-tree.json"), "utf8"));
const tagTarget = probe.tagObject.targetSha;
const pinned = probe.commit.sha;

const parentCommit = await get(`https://api.github.com/repos/${CANON}/git/commits/${tagTarget}`, "tag-delta-probe");
const parentTree = await get(
  `https://api.github.com/repos/${CANON}/git/trees/${parentCommit.tree.sha}?recursive=1`,
  "tag-delta-probe",
);

const parentBlobs = new Map(
  parentTree.tree.filter((e) => e.type === "blob").map((e) => [e.path, { sha: e.sha, size: e.size, mode: e.mode }]),
);
const pinnedBlobs = new Map(probe.blobIndex.map((e) => [e.path, { sha: e.sha, size: e.size, mode: e.mode }]));

const added = [];
const removed = [];
const modified = [];
for (const [path, v] of pinnedBlobs) {
  const p = parentBlobs.get(path);
  if (!p) added.push({ path, sha: v.sha, size: v.size });
  else if (p.sha !== v.sha) modified.push({ path, fromSha: p.sha, toSha: v.sha, fromSize: p.size, toSize: v.size });
}
for (const [path] of parentBlobs) if (!pinnedBlobs.has(path)) removed.push({ path, sha: parentBlobs.get(path).sha });

const changed = [...added.map((a) => a.path), ...removed.map((r) => r.path), ...modified.map((m) => m.path)];
const appSourcePrefixes = ["components/", "pages/", "public/", "styles/", "utils/", "services/", "src/", "config/"];
const appManifests = ["package.json", "package-lock.json", "next.config.js", "tailwind.config.js", "generate.js"];

const out = {
  schemaVersion: "versionless.legacy-corpus-tag-delta.v1",
  slug: "react-linkfree-v0-72-0",
  annotatedTag: {
    ref: probe.tagRef.ref,
    tagObjectSha: probe.tagObject.sha,
    tagMessage: probe.tagObject.message,
    taggerDate: probe.tagObject.taggerDate,
    tagSignatureVerified: probe.tagObject.verified,
    tagVerificationReason: probe.tagObject.verificationReason,
    targetCommitSha: tagTarget,
    targetCommitDate: parentCommit.committer.date,
    targetRootTreeSha: parentCommit.tree.sha,
  },
  pinnedCommit: {
    sha: pinned,
    date: probe.commit.committerDate,
    message: probe.commit.message,
    parents: probe.commit.parents,
    rootTreeSha: probe.commit.treeSha,
    signatureVerified: probe.commit.verified,
    verificationReason: probe.commit.verificationReason,
  },
  relationship:
    "The pinned commit is the DIRECT CHILD of the commit the annotated tag v0.72.0 points at. The pinned revision is one commit AFTER the v0.72.0 release tag, not the release tag itself.",
  delta: {
    parentBlobs: parentBlobs.size,
    pinnedBlobs: pinnedBlobs.size,
    added,
    removed,
    modified,
    changedPathCount: changed.length,
    changedPaths: changed.sort(),
    touchesApplicationSource: changed.some(
      (p) => appSourcePrefixes.some((pre) => p.startsWith(pre)) || appManifests.includes(p),
    ),
  },
};

writeFileSync(resolve(EVIDENCE, "tag-delta.json"), JSON.stringify(out, null, 2) + "\n");
appendFileSync(
  resolve(EVIDENCE, "transcript.ndjson"),
  JSON.stringify({
    at: new Date().toISOString(),
    step: "tag-delta-between-v0-72-0-and-pinned-commit",
    runner: "node evidence/ingests/react-linkfree-v0-72-0/drivers/01b-tag-delta.mjs",
    consentId: CONSENT,
    networkMode: "consented",
