// lrapr-t006/u5-ingest-linkfree — step 3: offline inventory of the reconciled source.
// No network. Profile data files under public/data are named by contributor username;
// they are counted and digested IN AGGREGATE and no individual username is emitted.

import { createHash } from "node:crypto";
import { appendFileSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, extname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const EVIDENCE = resolve(HERE, "..");
const REPO_ROOT = resolve(EVIDENCE, "../../..");
const SRC = resolve(
  REPO_ROOT,
  ".versionless/cache/react-linkfree-v0-72-0-source/verify/extracted/BioDrop-367d77297b5753644e11ecd22cf80e59c87b0dc8",
);

const sha256 = (b) => createHash("sha256").update(b).digest("hex");

const files = [];
