#!/usr/bin/env node
// lrapr-t006/u5-ingest-linkfree — step 7: redact contributor usernames from probe-tree.json.
//
// The recursive git tree lists every blob path, and every file under public/data is
// NAMED by a real contributor's GitHub username. Publishing that list verbatim would
// put 561 usernames into Versionless evidence, which this unit's packet forbids.
//
// The blob shas are NOT discarded: they are folded into an order-independent aggregate
// so the profile corpus stays verifiable against the tree without being enumerable.
// Every other path in the tree is left untouched.
//
// This runs AFTER reconciliation, which used the unredacted in-memory index, so no
// verification strength is lost — only the published enumeration is withheld.

import { createHash } from "node:crypto";
import { appendFileSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const EVIDENCE = resolve(HERE, "..");
const TARGET = resolve(EVIDENCE, "probe-tree.json");

const probe = JSON.parse(readFileSync(TARGET, "utf8"));
if (probe.blobIndexRedaction) {
  console.log("already redacted; nothing to do");
  process.exit(0);
}

const isProfileData = (p) => p.startsWith("public/data/");
const profile = probe.blobIndex.filter((e) => isProfileData(e.path));
const kept = probe.blobIndex.filter((e) => !isProfileData(e.path));

const aggregateBlobSha = createHash("sha256")
  .update(profile.map((e) => e.sha).sort().join("\n"))
  .digest("hex");

probe.blobIndex = kept;
probe.blobIndexRedaction = {
  redacted: true,
  reason:
    "Files under public/data are named by real contributor GitHub usernames. Enumerating them here would place 561 usernames into Versionless evidence, which this unit's packet forbids. The paths are withheld; the content is still addressable.",
  redactedPathPrefix: "public/data/",
  redactedEntryCount: profile.length,
  redactedTotalBytes: profile.reduce((a, e) => a + (e.size || 0), 0),
  aggregateBlobShaSha256: aggregateBlobSha,
  aggregateMethod:
    "sha256 over the sorted, newline-joined git blob shas of the redacted entries. Order-independent, so it can be recomputed from any checkout of the pinned revision and compared, without naming any contributor.",
  verificationUnaffected:
    "reconciliation.json was produced BEFORE this redaction, using the complete tree index, and reports 653 blobs with zero missing, zero extra and zero mismatched. The redaction withholds an enumeration from the published record; it does not weaken the parity proof.",
  blobIndexEntriesRetained: kept.length,
};

writeFileSync(TARGET, JSON.stringify(probe, null, 2) + "\n");
appendFileSync(
  resolve(EVIDENCE, "transcript.ndjson"),
  JSON.stringify({
    at: new Date().toISOString(),
    step: "redact-contributor-usernames-from-probe-tree",
    runner: "node evidence/ingests/react-linkfree-v0-72-0/drivers/07-redact-probe-tree.mjs",
    network: "none",
    nodeVersion: process.version,
    redactedEntries: profile.length,
    retainedEntries: kept.length,
  }) + "\n",
);

console.log(JSON.stringify({ redacted: profile.length, retained: kept.length, aggregateBlobShaSha256: aggregateBlobSha }, null, 2));

